-- --------------------------------------------------------------------
--  [수연] 자취 매물 실거래 시드 (rent_listing)
--  · 국토부 실거래가 API로 적재한 실매물 (가짜 mock 아님, 좌표 포함 → 지도·학교반경 검색 가능)
--  · 현재 수록: 서울 관악구(11620) 590건 - 서울대 반경검색 시연용
--  · 실행 순서: kb-schema.sql → kb-data.sql → 이 파일
--    (kb-schema에서 테이블을 새로 만든 뒤 실행해야 PK 중복이 안 남)
--  · 다른 지역 추가하려면:
--      1) POST /api/rent/listings/load?dealYm=202606&sigunguCodes=<시군구코드>  (좌표 포함, 학교검색용)
--      2) POST /api/rent/listings/load-nationwide?dealYm=202606                 (전국, 지역검색용)
--      3) 아래 명령으로 이 파일 재생성:
--         mysqldump -uscoula -p scoula_db rent_listing --no-create-info --complete-insert --compact --where="del_yn='N'" > kb-data-rent-listing.sql
-- --------------------------------------------------------------------

-- 재실행 안전장치: 기존 매물을 비우고 새로 넣는다 (WHERE 조건이 있어 safe update mode에서도 실행됨)
-- → 이 파일만 단독으로 다시 돌려도 PK(listing_id) 중복 없이 항상 최신 상태로 복원됨
-- rent_goal.confirmed_listing_id 등이 매물을 참조(FK)하므로, 비우는 동안 FK 체크를 잠시 끈다
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM rent_listing WHERE listing_id >= 1;
SET FOREIGN_KEY_CHECKS = 1;

